#!/usr/bin/env python3
# luxarch:escalation-remedy-tried hook v2 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""An escalation shows the documented remedy tried, in a commit, before it is filed.

PreToolUse(mcp__luxpm__luxpm_create_issue | mcp__luxpm__luxpm_update_issue): a create, or an update
that writes a guard escalation's title, is denied unless the description carries a `Kind:` line
and, for a kind that says the documented remedy does not work, a `Remedy applied: <sha>` line naming
a commit in this repository that applies it.

An issue is a guard escalation when its title opens with `[<guard> ESCALATION]` for luxarch, luxlint,
luxaudit or luxios (the `/escalate` title, read from the first line of `text` in the text form), or
it carries the label `fleet-escalation` beside a guard's own label. A maintainer's issue is not one:
a relay from an airgapped repo (a label `escalation-from-<project>`), a mirror of another project's
escalation (a title that opens with `[<KEY>-<n>]`), or a work issue (label `work-order` or `batch`)
without the escalation title. A title may name several guards (`[luxarch/luxlint ESCALATION]`). An update that sends no title, description or text (an answer: a comment,
`waiting_on`, labels) and an update that closes the issue are not judged.

The kinds (`/escalate`, "Is it an escalation?"):

- `false-red`, `remedy-fails`, `conflict`: the claim is that the rule's documented remedy cannot be
  applied here, or does not work. That claim is checked by trying it: the remedy is applied in the
  issue's worktree and committed, and the escalation names that commit. The commit must exist in
  this repository and change at least one file (a merge, against its first parent). For
  `false-red` and `remedy-fails` it is an attempt that reds or breaks the code, so it is not landed:
  no `main` / `master` / `dev` / `develop` / `trunk` branch, local or on a remote, no remote's HEAD
  branch, no `init.defaultBranch`, and not the main checkout's branch (unless it is the branch being
  worked on) contains it; an issue branch pushed so others can read it is not landed. For
  `conflict` it is every repo-side step that works, and it lands: the red stays lit on the one part
  the other requirement refuses, and nothing else waits on the escalation. A landed conflict commit
  changes a file the escalation names, and a conflict names its other requirement on a
  `Conflicts with:` line. A field's value is its first token. If the remedy clears the red, there
  is nothing to escalate: land it.
- `false-green`, `asset-defect`, `missing-rule`: broken code that the rule passes, an emitted asset
  that fails unedited, or a fleet concern no rule checks. No remedy exists to apply, so no commit is
  asked for.

**Why a hook.** "Could the maintainer answer 'apply the remedy in the fix text'? Then it is not an
escalation" is a test the filing agent judges for itself, and filing is pre-authorized, so a move
the standard already covered was escalated whole when it looked large. Whether the remedy was tried
is in no file a guard scans at filing time; the commit is.

Limits: the hook checks that an attempt exists, not that it is the right remedy (the maintainer's
triage answers a wrong one with `not-an-escalation`). An update that sends only a description, an
existing issue relabelled as an escalation without its title, and an issue made through
`luxpm_chat` are not seen: each would need the issue read back from LuxPM. A title that opens with
any `[<KEY>-<n>]` tag reads as a mirror. Fields inside a code fence or a `>` quote are not read: they are
someone else's text. Fails OPEN on an event it cannot read (a process gate); a remedy commit git
cannot find, or cannot check (no git, a timeout), is denied, with what git said.
"""

from __future__ import annotations

import json
import os
import re
import subprocess
import sys

_CREATE = "mcp__luxpm__luxpm_create_issue"
_UPDATE = "mcp__luxpm__luxpm_update_issue"
_LABEL = "fleet-escalation"
_GUARDS = ("luxarch", "luxlint", "luxaudit", "luxios")
_WORK_LABELS = {"work-order", "batch"}
_NEEDS_COMMIT = ("false-red", "remedy-fails", "conflict")
_NO_COMMIT = ("false-green", "asset-defect", "missing-rule")
_LONG_LIVED = {"main", "master", "dev", "develop", "trunk"}
_MIRROR = re.compile(r"^\s*\[[A-Z][A-Z0-9]*-\d+\]")
_GUARD_TITLE = re.compile(
    r"^\s*\[[^\]]*\b(?:luxarch|luxlint|luxaudit|luxios)\b[^\]]*\bescalation\]",
    re.IGNORECASE,
)
_FENCE = re.compile(r"^\s*(```|~~~)")
_QUOTED = re.compile(r"^\s*>")  # a quote: someone else's text
_PREFIX = re.compile(r"^\s*(?:[-*+#]+\s*|\d+[.)]\s*)*")
_FIELD_AT = re.compile(
    r"(?:^|(?<=[\s.;,(]))(kind|remedy applied|conflicts with)\s*:\s*", re.IGNORECASE
)
_KIND_WORD = re.compile(r"[a-z][a-z_-]*")
_HEX = re.compile(r"(?<![0-9a-z])[0-9a-f]{7,40}(?![0-9a-z])")
_SHA = re.compile(r"^[0-9a-f]{7,40}$")
_TIMEOUT = 5


def _fields(text: str) -> tuple[list[tuple[str, str]], bool]:
    """(`kind` | `remedy applied`, value) for each field in the author's own text, in order, and
    whether a field was passed over inside a code fence or a quote.

    A field may stand on its own line, in a list, a heading or a table row, or inline after other
    fields (`**Guard:** luxarch 0.366.0. **Kind:** false-red.`).
    """
    out: list[tuple[str, str]] = []
    skipped = False
    fenced = False
    for raw in text.splitlines():
        if _FENCE.match(raw):
            fenced = not fenced
            continue
        line = raw.replace("*", "").replace("`", "")
        if fenced or _QUOTED.match(line):
            skipped = skipped or bool(_FIELD_AT.search(line))
            continue
        line = line.strip()
        cells = (
            [c.strip() for c in line.strip("|").split("|")]
            if line.startswith("|")
            else []
        )
        if len(cells) >= 2:
            line = f"{cells[0]}: {cells[1]}"
        line = _PREFIX.sub("", line, count=1)
        hits = list(_FIELD_AT.finditer(line))
        for i, hit in enumerate(hits):
            end = hits[i + 1].start() if i + 1 < len(hits) else len(line)
            key, value = hit.group(1).lower(), line[hit.end() : end].strip().lower()
            if not value:
                continue
            if key == "kind":
                word = _KIND_WORD.match(value)  # the kind, without what follows it
                if word:
                    out.append((key, word.group(0).replace("_", "-").rstrip("-")))
                continue
            if key == "conflicts with":
                out.append((key, value))
                continue
            # the field's value is its first token (a sha or a commit link); a sha further on in
            # the line is kept apart, read only where an attempt may follow its base
            first = value.split()[0]
            lead = _HEX.findall(first)
            out.append((key, lead[-1] if lead else first))
            out += [("remedy also", s) for s in _HEX.findall(value[len(first) :])]
    return out, skipped


def _title(entry: dict[str, object]) -> str:
    title = entry.get("title")
    if isinstance(title, str) and title.strip():
        return title
    text = entry.get("text")
    return (
        text.strip().splitlines()[0] if isinstance(text, str) and text.strip() else ""
    )


def _labels(entry: dict[str, object]) -> set[str]:
    raw = entry.get("labels")
    items = raw if isinstance(raw, list) else [raw] if isinstance(raw, str) else []
    return {str(x).strip().lower() for x in items}


def _is_escalation(entry: dict[str, object]) -> bool:
    title = _title(entry)
    labels = _labels(entry)
    if any(x.startswith("escalation-from-") for x in labels) or _MIRROR.match(title):
        return False  # a relay from an airgapped repo, or a mirror of another project's escalation
    if _GUARD_TITLE.search(title):
        return True  # the /escalate title, whatever topic labels ride along
    if labels & _WORK_LABELS:
        return False  # the maintainer's work issue
    return _LABEL in labels and bool(labels & set(_GUARDS))


def _judged(name: str, entry: dict[str, object]) -> bool:
    if name == _UPDATE:
        if str(entry.get("state") or "") in ("done", "cancelled"):
            return False
        if not any(entry.get(k) for k in ("title", "description", "text")):
            return False
    return _is_escalation(entry)


def _git(cwd: str, *args: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        ["git", "-C", cwd, *args],
        capture_output=True,
        text=True,
        timeout=_TIMEOUT,
        check=False,
    )


def _repo_for(sha: str, dirs: list[str]) -> tuple[str, str]:
    """(the directory whose repository holds commit `sha`, '') or ('', what git said)."""
    said = ""
    for d in dirs:
        if not d:
            continue
        r = _git(d, "cat-file", "-t", sha)
        if r.stdout.strip() == "commit":
            return d, ""
        if not said and r.stderr.strip():
            said = r.stderr.strip().splitlines()[0]
    return "", said


def _landed_on(cwd: str, sha: str) -> str:
    """A long-lived ref that already holds `sha`, or ''."""
    long_lived = set(_LONG_LIVED)
    default = _git(cwd, "config", "--get", "init.defaultBranch").stdout.strip()
    if default:
        long_lived.add(default)
    current = _git(cwd, "symbolic-ref", "-q", "--short", "HEAD").stdout.strip()
    porcelain = _git(cwd, "worktree", "list", "--porcelain").stdout
    for line in porcelain.split("\n\n", 1)[
        0
    ].splitlines():  # the main checkout's stanza only
        if line.startswith("branch "):
            main_branch = line.split(" ", 1)[1].removeprefix("refs/heads/")
            if main_branch != current:  # the branch being worked on is not its own base
                long_lived.add(main_branch)
    remote_heads: set[str] = set()
    listing = _git(
        cwd, "for-each-ref", "--format=%(refname) %(symref)", "refs/remotes"
    ).stdout
    for line in listing.splitlines():
        name, _, target = line.partition(" ")
        if name.endswith("/HEAD") and target:
            remote_heads.add(target)
    refs = _git(
        cwd, "for-each-ref", "--contains", sha, "--format=%(refname)"
    ).stdout.split()
    for ref in refs:
        if ref.startswith("refs/remotes/") and not ref.endswith("/HEAD"):
            branch = ref.removeprefix("refs/remotes/").split("/", 1)[-1]
            if ref in remote_heads or branch in long_lived:
                return ref.removeprefix("refs/remotes/")
        if (
            ref.startswith("refs/heads/")
            and ref.removeprefix("refs/heads/") in long_lived
        ):
            return ref.removeprefix("refs/heads/")
    return ""


def _commit_problem(dirs: list[str], sha: str, kind: str, text: str = "") -> str:
    """Why `sha` is not a remedy attempt in this repository, or '' when it is one. A conflict's
    commit (every repo-side step that works) may be landed, and then changes a file the
    escalation names; any other kind's attempt may not be landed."""
    if not _SHA.match(sha):
        return f"`{sha}` is not a commit sha."
    cwd, said = _repo_for(sha, dirs)
    if not cwd:
        why = f" git: {said}" if said else ""
        return f"`{sha}` is not a commit in this repository ({dirs[0]}).{why}"
    if _git(cwd, "rev-parse", "-q", "--verify", sha + "^1").returncode == 0:
        changed = _git(cwd, "diff", "--name-only", sha + "^1", sha).stdout
    else:
        changed = _git(
            cwd, "diff-tree", "--no-commit-id", "--name-only", "-r", "--root", sha
        ).stdout
    if not changed.strip():
        return f"`{sha}` changes no file: an attempt at the remedy changes the code or config it is about."
    landed = _landed_on(cwd, sha)
    if kind == "conflict" and landed:
        files = [f for f in changed.split() if f]
        named = [f for f in files if f in text or f.rsplit("/", 1)[-1] in text]
        if named:
            return ""
        return (
            f"`{sha}` is on {landed} and changes none of the files this escalation names "
            f"({', '.join(files[:4])}{', ...' if len(files) > 4 else ''}): a conflict's landed "
            "commit is the repo-side steps for the site it names. Name the file in the Verify."
        )
    if landed:
        return f"`{sha}` is already on {landed}: that is the state the guard judged, not an attempt at its remedy."
    return ""


def _judge(entry: dict[str, object], dirs: list[str]) -> str:
    """Why this escalation is refused, or '' to allow it."""
    raw = entry.get("description")
    if raw is None:
        raw = entry.get("text")
    text = str(raw or "")
    if not text.strip():
        return (
            "it carries no description here. Writing an escalation's title sends its description "
            "too, with its `Kind:` line (and `Remedy applied:` where the kind needs it)."
        )
    fields, skipped = _fields(text)
    kinds = [v for k, v in fields if k == "kind"]
    if not kinds:
        if skipped:
            return (
                "its `Kind:` line is inside a quote or a code fence, which is someone else's text "
                "and is not read: write it in your own text."
            )
        return "its description has no `Kind:` line."
    known = [v for v in kinds if v in _NEEDS_COMMIT + _NO_COMMIT]
    if not known:
        return f"`Kind: {kinds[0]}` is not a kind of escalation."
    kind = known[0]
    if kind in _NO_COMMIT:
        return ""
    if kind == "conflict" and not [v for k, v in fields if k == "conflicts with"]:
        return (
            "`Kind: conflict` names no second requirement: add `Conflicts with: <the other "
            "rule or doc section>`. Correct code a rule reds is `Kind: false-red`."
        )
    shas = [v for k, v in fields if k == "remedy applied"]
    if kind != "conflict":
        shas += [v for k, v in fields if k == "remedy also"]
    if not shas:
        return (
            f"`Kind: {kind}` says the documented remedy does not work here, and names no "
            "`Remedy applied: <sha>` commit that tried it."
        )
    problems = [
        _commit_problem(dirs, s, kind, text) for s in shas
    ]  # the attempt may follow the base it was made on
    return "" if "" in problems else problems[0]


def main() -> int:
    try:
        ev = json.load(sys.stdin)
        name = str(ev.get("tool_name") or "")
        inp = ev.get("tool_input")
        if not isinstance(inp, dict) or name not in (_CREATE, _UPDATE):
            return 0
        updates = inp.get("updates")
        if name == _UPDATE and isinstance(updates, list):
            entries = [e for e in updates if isinstance(e, dict)]
        else:
            entries = [inp]
        dirs = [
            str(ev.get("cwd") or os.getcwd()),
            os.environ.get("CLAUDE_PROJECT_DIR", ""),
        ]
    except (
        Exception
    ):  # swallowed-exceptions: an unreadable event fails open (a process gate)
        return 0
    for entry in entries:
        try:
            if not _judged(name, entry):
                continue
            why = _judge(entry, dirs)
        except (
            Exception
        ) as exc:  # swallowed-exceptions: git could not answer; refuse, naming it
            why = f"the remedy commit could not be checked ({type(exc).__name__})."
        if why:
            title = str(_title(entry) or entry.get("sequence_id") or "")[:120]
            print(
                f"DENIED: an escalation shows the documented remedy tried. {title!r}: {why}\n"
                "Before filing, apply the rule's documented remedy (its --doc / --playbook steps) in\n"
                "this issue's worktree and commit it. If the red clears, it was never an escalation:\n"
                "land it. Land every step that works now: an escalation holds back one site, never\n"
                "the rest of the work. An attempt that still reds or breaks the code (false-red,\n"
                "remedy-fails) stays on a branch (`git branch escalation/<KEY> <sha>`). Two guard\n"
                "requirements that cannot both be met are a conflict: its commit is the repo-side\n"
                "steps that work, landed, and it names the other requirement. File with:\n"
                "  Kind: <one of false-red, remedy-fails, conflict>\n"
                "  Remedy applied: <sha of that commit>\n"
                "  Conflicts with: <the other rule or doc section>   (conflict only)\n"
                "and a Verify whose 'now' output is the rule run on that commit. Broken code the rule\n"
                "passes is `Kind: false-green`, an unedited emitted asset that fails is\n"
                "`Kind: asset-defect`, a fleet concern no rule checks is `Kind: missing-rule`: none\n"
                "needs a commit. A step for infra, the owner or another repo is a request to them,\n"
                "never an escalation (FLEET-AGENT-CONDUCT-STANDARD #7). /escalate has the steps.",
                file=sys.stderr,
            )
            return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
